import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Meditation y Concentration","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/magic/meditation-and-concentration.md","filePath":"es/guide/magic/meditation-and-concentration.md"}'),o={name:"es/guide/magic/meditation-and-concentration.md"};function r(d,a,c,s,l,m){return t(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="meditation-concentration" tabindex="-1">Meditation y Concentration <a class="header-anchor" href="#meditation-concentration" aria-label="Enlace permanente a &quot;Meditation y Concentration&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · Disponibilidad no confirmada.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Meditation se ocupa de recuperación, organización y preparación.</li><li><a href="/Syrolands-Public/es/guide/glossary.html#concentration">Concentration</a> (concentración) significa estabilidad bajo presión, no automáticamente otra <a href="/Syrolands-Public/es/guide/characters/skills.html">habilidad</a> con límite.</li><li>Fallar al ejecutar un hechizo y sufrir la interrupción de un lanzamiento son sucesos distintos.</li></ul><p><span id="meditation-and-concentration"></span><span id="at-a-glance"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Elemento</th><th>Qué significa para el jugador</th></tr></thead><tbody><tr><td>Meditation</td><td>Puede ayudar a organizar <a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Active Memory</a> (memoria activa), preparar patrones difíciles y recuperar la disposición mental.</td></tr><tr><td>Concentration</td><td>Puede verse comprometida por daño, movimiento, <a href="/Syrolands-Public/es/guide/glossary.html#fatigue">fatiga</a>, trauma y lanzamientos complejos.</td></tr><tr><td>Fizzle (fallo de ejecución)</td><td>La estructura mágica no se ejecuta correctamente.</td></tr><tr><td>Interrupción</td><td>La presión interrumpe un intento de lanzamiento. Los costes exactos de ambos resultados siguen abiertos.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Orientación de Syrolands</th></tr></thead><tbody><tr><td>Meditation apoya la regeneración de maná, activa y pasivamente.</td><td>También se exploran la organización mental, la preparación y la recuperación de la disposición mental.</td></tr><tr><td>El lanzamiento ya implica comprobaciones de éxito y posibles interrupciones.</td><td>Se distingue el fallo de ejecución de la estabilidad bajo presión y las lesiones localizadas.</td></tr></tbody></table><p>Las reglas de UO varían según la época y el shard. <a href="https://uo.com/wiki/ultima-online-wiki/skills/magery/" target="_blank" rel="noreferrer">UO oficial: Magery y Meditation</a>.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un mago con mucho maná aún puede tener dificultades bajo presión repetida. Encontrar un respiro podría importar tanto como recuperar recursos antes de intentar un patrón difícil.</p><h2 id="progression-trade-offs" tabindex="-1">Progresión y contrapartidas <a class="header-anchor" href="#progression-trade-offs" aria-label="Enlace permanente a &quot;Progresión y contrapartidas&quot;">​</a></h2><p>Los estados mentales aprendidos deberían implicar compromisos y contrapartidas. No hay una lista definitiva de trances, cambios gratuitos en combate, bonificaciones numéricas ni fórmulas de interrupción.</p><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/magic/memory-and-familiarity.html">Memoria</a> · <a href="/Syrolands-Public/es/guide/magic/overview.html">Magery</a> · <a href="/Syrolands-Public/es/guide/combat/stamina-and-reactive-combat.html">Stamina y Flow</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p>Consulta la especificación de diseño: <a href="/Syrolands-Public/es/game-design/magic.html#meditation-and-concentration">Meditation y Concentration</a>.</p>',18)])])}const h=e(o,[["render",r]]);export{u as __pageData,h as default};
